// expect: exit 57
// screen: 0 middle x 3, sum 57
typedef struct point { int x; int y; } Point;
Point pts[3] = { { 1, 2 }, { 3, 4 }, { 5, 6 } };
int main(void)
{
    int i, sum = 0;
    Point *q = &pts[1];
    q->y = 40;
    for (i = 0; i < 3; i++)
        sum += pts[i].x + pts[i].y;
    cls();
    printf("middle x %d, sum %d\n", pts[1].x, sum);
    return sum;
}
